#include <iostream>
using namespace std;

int main() {
    int heap[7] = {50, 30, 40, 10, 20, 35, 25};
    int size = 7;
    int i = 1;
    int left = 2 * i + 1;
    int right = 2 * i + 2;
    cout << "Children of " << heap[i] << ": " << heap[left] << " and " << heap[right] << endl;
    int child = 6;
    while (child > 0) {
        int parent = (child - 1) / 2;
        cout << heap[child] << " -> " << heap[parent] << endl;
        child = parent;
    }
    return 0;
}
